"use client";

import { loadFont as loadMono } from "@remotion/google-fonts/GeistMono";
import { loadFont as loadSans } from "@remotion/google-fonts/Inter";
import { format, parseISO } from "date-fns";
import { memo, useMemo, useState } from "react";
import {
  AbsoluteFill,
  Easing,
  Img,
  interpolate,
  random,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { Odometer } from "@/registry/snap-cn/counter";

export interface Stargazer {
  login: string;
  avatarUrl: string;
  /** ISO date string, e.g. "2026-06-21" */
  starredAt: string;
}

export interface GitHubStarsProps {
  repo?: string;
  /** Star count the odometer locks on. */
  totalStars?: number;
  /**
   * Star count the odometer starts from. Leave at 0 for a full count-up;
   * set close to `totalStars` for a milestone clip (e.g. 9940 → 10000).
   */
  startStars?: number;
  stargazers?: Stargazer[];
  orientation?: "horizontal" | "vertical";
  /** snap-cn accent — underline, active-row bar, celebration particles. */
  accentColor?: string;
  /** GitHub-native starred gold. Platform chrome — change sparingly. */
  starColor?: string;
  speed?: number;
  theme?: "light" | "dark";
  /** Fire the restrained particle burst when the counter locks. */
  celebrate?: boolean;
  /** Optional caption shown under the repo slug once the counter locks. */
  milestoneLabel?: string;
  repoAvatarUrl?: string;
}

/**
 * Built-in mock stargazers so the composition renders immediately from
 * defaults (own-your-code: no external data needed after `shadcn add`).
 * Framed as the last 60 stargazers before a fictional repo crosses 10,000
 * stars. Handles are fictional; real low-id GitHub avatar URLs are CORS-ok,
 * so the docs preview shows round photos (with an initial-letter fallback).
 */
const MILESTONE_LOGINS = [
  "mira-codes",
