  "sam-builds",
  "nils-io",
  "rosa-dev",
  "jun-codes",
  "femi-builds",
  "elsa-ops",
  "omar-dev",
  "ivy-ships",
  "theo-codes",
  "lena-builds",
  "arjun-io",
  "cleo-dev",
  "marco-ships",
  "nora-codes",
  "ravi-builds",
  "sofia-dev",
  "jack-ops",
  "emi-codes",
  "hugo-ships",
  "tessa-dev",
  "yuki-builds",
  "colin-io",
  "dara-codes",
  "felix-ops",
  "gina-dev",
  "hana-ships",
  "iker-codes",
  "jade-builds",
  "kian-dev",
  "lila-io",
  "milo-codes",
  "nina-ops",
  "otis-dev",
  "pia-ships",
  "quinn-codes",
  "ruby-builds",
  "seth-dev",
  "tara-io",
  "umar-codes",
  "vera-ops",
  "wes-dev",
  "xena-ships",
  "yara-codes",
  "zane-builds",
  "globex-eng",
  "initech-io",
  "vandelay-dev",
  "acme-labs-bot",
  "dana-ships",
];

export const SAMPLE_STARGAZERS: Stargazer[] = MILESTONE_LOGINS.map(
  (login, i) => ({
    login,
    avatarUrl: `https://avatars.githubusercontent.com/u/${i + 1}?v=4`,
    // The final sprint to 10k: ~7 stars a day across late June 2026.
    starredAt: `2026-06-${String(21 + Math.floor(i / 7)).padStart(2, "0")}`,
  }),
);

// Load fonts INSIDE the composition (via @remotion/google-fonts, which waits
// for the font with delayRender before rendering frames). Server renders run
// in a bare headless Chromium with no app CSS / `--font-*` vars, so without
// this the MP4 falls back to the default sans-serif. Inter for UI text (the
// snap-cn sans), Geist Mono for the numeric row index.
const { fontFamily: SANS_FAMILY } = loadSans("normal", {
  weights: ["400", "500", "600"],
  subsets: ["latin"],
});
const { fontFamily: MONO_FAMILY } = loadMono("normal", {
  weights: ["400"],
  subsets: ["latin"],
});

const FONT_FAMILY = SANS_FAMILY;

interface Theme {
  /** Scene canvas behind everything. */
  canvas: string;
  /** Surface — the list card. */
  bg: string;
  /** Subtle surface — active-row wash, avatar fallback. */
  bgSubtle: string;
  fg: string;
  fgMuted: string;
  border: string;
}

// snap-cn design tokens: light-first, hairline borders, muted grays.
const THEMES: Record<"light" | "dark", Theme> = {
  light: {
    canvas: "#FAFAFA",
    bg: "#FFFFFF",
    bgSubtle: "#F2F4F7",
    fg: "#101828",
    fgMuted: "#667085",
    border: "#E4E7EC",
  },
  dark: {
    canvas: "#0A0A0B",
    bg: "#141417",
    bgSubtle: "#1D1D21",
    fg: "#FAFAFA",
    fgMuted: "#A1A1AA",
    border: "#26272B",
  },
};

/** GitHub's starred-state gold — authentic platform chrome. */
export const GITHUB_STAR_GOLD = "#EAC54F";

/** Restrained blue celebration palette derived from the snap-cn accent. */
export const CELEBRATION_COLORS = ["#266DF0", "#1D5BD6", "#7FA6F7", "#C3D5FB"];

// --- Pure helpers (unit-tested) -------------------------------------------

/**
 * Clamp a stargazer list to at most `max` evenly-sampled keyframe rows while
 * always preserving the first and last entry. Safety net for callers that pass
 * a huge array straight into the composition.
 */
export function downsampleStargazers(
  stargazers: Stargazer[],
  max = 60,
): Stargazer[] {
  const len = stargazers.length;
  if (len <= max) return stargazers;
  if (max <= 1) return len ? [stargazers[0]] : [];
  const out: Stargazer[] = [];
  for (let i = 0; i < max; i++) {
    out.push(stargazers[Math.round((i * (len - 1)) / (max - 1))]);
  }
  return out;
}

const MAX_ELASTIC_OVERSHOOT = 0.0658; // Easing.elastic(1) peak−1 (true ≈0.0657267), rounded UP for use as a safety bound
const SCROLL_OVERSHOOT = 1 + MAX_ELASTIC_OVERSHOOT; // ≈1.0658
const MASK_SOLID_FRACTION = 0.88; // bottom fade mask is solid until 88% of viewport height
const COUNT_PORTION = 0.8;

/** Monotonic counter ramp — mirrors the reference StarCount easing. Drives the
 *  odometer, which must stay monotonic or the digit wheels roll backward. */
export function computeCounterProgress({
  frame,
  speed = 1,
  durationInFrames,
}: {
  frame: number;
  speed?: number;
  durationInFrames: number;
}): number {
  return interpolate(
    frame * speed,
    [0, durationInFrames * COUNT_PORTION],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.bezier(0.5, 1, 0.5, 1),
    },
  );
}

/** Elastic scroll ramp — mirrors the reference avatar slide. NON-monotonic:
 *  overshoots to ~SCROLL_OVERSHOOT near t≈0.63 and settles to exactly 1 at t=1.
 *  Drives only scrollY (never the odometer). */
export function computeScrollProgress({
  frame,
  speed = 1,
  durationInFrames,
}: {
  frame: number;
  speed?: number;
  durationInFrames: number;
}): number {
  return interpolate(frame * speed, [0, durationInFrames], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.elastic(0.8),
  });
}

/** Empty rows appended below the last stargazer so the elastic recoil never
 *  lifts real content off the mask-solid zone, revealing a void. Single source
 *  of truth shared with isScrollContained so the two cannot drift. */
export function computeSpacerRows({
  N,
  rowH,
  viewportH,
  visibleRows,
}: {
  N: number;
  rowH: number;
  viewportH: number;
  visibleRows: number;
}): number {
  const D = Math.max(0, (N - visibleRows + 1) * rowH);
  const needPx =
    MASK_SOLID_FRACTION * viewportH - N * rowH + SCROLL_OVERSHOOT * D;
  return Math.max(0, Math.ceil(needPx / rowH));
}

/** True when, at the elastic overshoot peak, content still fills the mask-solid
 *  zone (no void revealed). True by construction given computeSpacerRows. */
export function isScrollContained({
  N,
  rowH,
  viewportH,
  visibleRows,
}: {
  N: number;
  rowH: number;
  viewportH: number;
  visibleRows: number;
}): boolean {
  const D = Math.max(0, (N - visibleRows + 1) * rowH);
  const spacerPx =
    computeSpacerRows({ N, rowH, viewportH, visibleRows }) * rowH;
  return (
    N * rowH + spacerPx - SCROLL_OVERSHOOT * D >=
    MASK_SOLID_FRACTION * viewportH
  );
}

/** The running counter value for a given progress. Counts from `startStars`
 *  (clamped to `totalStars`) up to `totalStars` and locks there. */
export function getStarCount(
  counterProgress: number,
  totalStars: number,
  startStars = 0,
): number {
  const start = Math.min(Math.max(0, startStars), totalStars);
  return Math.round(start + counterProgress * (totalStars - start));
}

export interface CelebrationParticle {
  /** Emission angle in radians. */
  angle: number;
  /** Travel distance in reference px. */
  distance: number;
  /** Dot diameter in reference px. */
  size: number;
  /** Index into CELEBRATION_COLORS. */
  colorIndex: number;
  /** Per-particle start offset as a fraction of the burst window [0, 0.35]. */
  delay: number;
}

/** Deterministic particle descriptors for the milestone burst. Uses
 *  Remotion's seeded random() — same seed, same burst, every render. */
export function buildCelebrationParticles(
  count = 18,
  seed = "github-stars",
): CelebrationParticle[] {
  const particles: CelebrationParticle[] = [];
  for (let i = 0; i < count; i++) {
    const jitter = (random(`${seed}-angle-${i}`) - 0.5) * (Math.PI / count);
    particles.push({
      angle: (i / count) * Math.PI * 2 + jitter,
      distance: 90 + random(`${seed}-dist-${i}`) * 110,
      size: 5 + random(`${seed}-size-${i}`) * 5,
      colorIndex: i % CELEBRATION_COLORS.length,
      delay: random(`${seed}-delay-${i}`) * 0.35,
    });
  }
  return particles;
}

/** Linear 0→1 ramp across the tail of the timeline — starts the moment the
 *  counter locks (COUNT_PORTION) and finishes on the final frame. */
export function computeCelebrationProgress({
  frame,
  speed = 1,
  durationInFrames,
}: {
  frame: number;
  speed?: number;
  durationInFrames: number;
}): number {
  return interpolate(
    frame * speed,
    [durationInFrames * COUNT_PORTION, durationInFrames],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
  );
}

// --- Sub-components --------------------------------------------------------

function StarGlyph({ size, fill }: { size: number; fill: string }) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      width={size}
      height={size}
      color={fill}
      fill={fill}
      stroke={fill}
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <title>Stars</title>
      <path d="M13.7276 3.44418L15.4874 6.99288C15.7274 7.48687 16.3673 7.9607 16.9073 8.05143L20.0969 8.58575C22.1367 8.92853 22.6167 10.4206 21.1468 11.8925L18.6671 14.3927C18.2471 14.8161 18.0172 15.6327 18.1471 16.2175L18.8571 19.3125C19.417 21.7623 18.1271 22.71 15.9774 21.4296L12.9877 19.6452C12.4478 19.3226 11.5579 19.3226 11.0079 19.6452L8.01827 21.4296C5.8785 22.71 4.57865 21.7522 5.13859 19.3125L5.84851 16.2175C5.97849 15.6327 5.74852 14.8161 5.32856 14.3927L2.84884 11.8925C1.389 10.4206 1.85895 8.92853 3.89872 8.58575L7.08837 8.05143C7.61831 7.9607 8.25824 7.48687 8.49821 6.99288L10.258 3.44418C11.2179 1.51861 12.7777 1.51861 13.7276 3.44418Z"></path>
    </svg>
  );
}

function Avatar({
  login,
  avatarUrl,
  size,
  theme,
}: {
  login: string;
  avatarUrl: string;
  size: number;
  theme: Theme;
}) {
  const [errored, setErrored] = useState(false);
  const ringStyle = {
    width: size,
    height: size,
    borderRadius: 9999,
    border: `1px solid ${theme.border}`,
    flexShrink: 0,
  } as const;

  if (errored || !avatarUrl) {
    return (
      <div
        style={{
          ...ringStyle,
          background: theme.bgSubtle,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          color: theme.fgMuted,
          fontSize: size * 0.42,
          fontWeight: 600,
        }}
      >
        {login.charAt(0).toUpperCase()}
      </div>
    );
  }

  return (
    <Img
      src={avatarUrl}
      crossOrigin="anonymous"
      onError={() => setErrored(true)}
      style={{ ...ringStyle, objectFit: "cover" }}
    />
  );
}

interface RowProps {
  stargazer: Stargazer;
  index: number;
  rowH: number;
  avatarSize: number;
  loginSize: number;
  dateLabel: string;
  accent: string;
  starFill: string;
  theme: Theme;
  isActive: boolean;
  settle: number;
  showSeparator: boolean;
  opacity: number;
}

const Row = memo(function Row({
  stargazer,
  index,
  rowH,
  avatarSize,
  loginSize,
  dateLabel,
  accent,
  starFill,
  theme,
  isActive,
  settle,
  showSeparator,
  opacity,
}: RowProps) {
  return (
    <div
      style={{
        position: "relative",
        height: rowH,
        display: "flex",
        alignItems: "center",
        paddingLeft: 24,
        paddingRight: 24,
        background: "transparent",
        opacity,
        boxSizing: "border-box",
        borderBottom:
          showSeparator && !isActive ? `1px solid ${theme.border}` : "none",
      }}
    >
      {isActive && (
        <>
          <div
            style={{
              position: "absolute",
              inset: 0,
              background: theme.bgSubtle,
              opacity: settle,
            }}
          />
          <div
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              bottom: 0,
              width: 2,
              background: accent,
              opacity: settle,
            }}
          />
        </>
      )}
      <div
        style={{
          position: "relative",
          display: "flex",
          alignItems: "center",
          width: "100%",
        }}
      >
        <Avatar
          login={stargazer.login}
          avatarUrl={stargazer.avatarUrl}
          size={avatarSize}
          theme={theme}
        />
        <div style={{ marginLeft: 20, minWidth: 0, flex: 1 }}>
          <div
            style={{
              fontSize: loginSize,
              fontWeight: 600,
              color: theme.fg,
              fontFamily: FONT_FAMILY,
              letterSpacing: "-0.01em",
              whiteSpace: "nowrap",
              overflow: "hidden",
              textOverflow: "ellipsis",
              lineHeight: 1.2,
            }}
          >
            {stargazer.login}
          </div>
          <div
            style={{
              fontSize: 18,
              fontWeight: 400,
              color: theme.fgMuted,
              fontFamily: FONT_FAMILY,
              lineHeight: 1.3,
            }}
          >
            {dateLabel}
          </div>
        </div>
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 8,
            color: theme.fgMuted,
            fontFamily: MONO_FAMILY,
            fontSize: 18,
            fontVariantNumeric: "tabular-nums",
            flexShrink: 0,
          }}
        >
          <StarGlyph size={20} fill={starFill} />
          <span>#{index + 1}</span>
        </div>
      </div>
    </div>
  );
});

function CelebrationBurst({
  progress,
  originX,
  originY,
}: {
  progress: number;
  originX: number;
  originY: number;
}) {
  const particles = useMemo(() => buildCelebrationParticles(), []);
  if (progress <= 0) return null;
  return (
    <div
      style={{
        position: "absolute",
        left: originX,
        top: originY,
        width: 0,
        height: 0,
        pointerEvents: "none",
      }}
      aria-hidden="true"
    >
      {particles.map((p, i) => {
        const local = Math.max(
          0,
          Math.min(1, (progress - p.delay) / (1 - p.delay)),
        );
        if (local <= 0) return null;
        const eased = 1 - (1 - local) ** 3; // fast ease-out, no bounce
        const x = Math.cos(p.angle) * p.distance * eased;
        const y = Math.sin(p.angle) * p.distance * eased;
        const opacity = interpolate(local, [0, 0.12, 0.7, 1], [0, 1, 1, 0]);
        const scale = 1 - 0.35 * local;
        return (
          <div
            key={`particle-${
              // biome-ignore lint/suspicious/noArrayIndexKey: static deterministic list
              i
            }`}
            style={{
              position: "absolute",
              width: p.size,
              height: p.size,
              borderRadius: 9999,
              background: CELEBRATION_COLORS[p.colorIndex],
              transform: `translate(${x - p.size / 2}px, ${
                y - p.size / 2
              }px) scale(${scale})`,
              opacity,
            }}
          />
        );
      })}
    </div>
  );
}

// --- Main composition ------------------------------------------------------

export function GitHubStars({
  repo = "acme-labs/cli",
  totalStars = 10000,
  startStars = 0,
  stargazers = SAMPLE_STARGAZERS,
  orientation = "horizontal",
  accentColor = "#266DF0",
  starColor = GITHUB_STAR_GOLD,
  speed = 1,
  theme = "light",
  celebrate = true,
  milestoneLabel = "",
  repoAvatarUrl,
}: GitHubStarsProps) {
  const frame = useCurrentFrame();
  const { durationInFrames, width, height } = useVideoConfig();
  const t = THEMES[theme] ?? THEMES.light;
  const isVertical = orientation === "vertical";

  // Render at the native reference size for the orientation, then scale to fit
  // the actual canvas — keeps proportions at any resolution and letterboxes a
  // vertical layout cleanly inside a horizontal preview canvas.
  const refW = isVertical ? 720 : 1280;
  const refH = isVertical ? 1280 : 720;
  const stageScale = Math.min(width / refW, height / refH);

  const rows = useMemo(() => downsampleStargazers(stargazers), [stargazers]);
  const N = rows.length;

  // Progress drivers: monotonic counter ramp + non-monotonic elastic scroll.
  const counterProgress = computeCounterProgress({
    frame,
    speed,
    durationInFrames,
  });
  const pScroll = computeScrollProgress({ frame, speed, durationInFrames });
  const p = Math.max(0, Math.min(1, (frame * speed) / durationInFrames));

  const start = Math.min(Math.max(0, startStars), totalStars);
  const current = start + counterProgress * (totalStars - start);

  const celebrationProgress = celebrate
    ? computeCelebrationProgress({ frame, speed, durationInFrames })
    : 0;

  // List viewport geometry (in reference px).
  const rowH = isVertical ? 96 : 88;
  const avatarSize = isVertical ? 60 : 56;
  const loginSize = isVertical ? 30 : 28;
  const dateFormat = isVertical ? "MMM yyyy" : "MMM d, yyyy";
  const formattedRows = useMemo(
    () =>
      rows.map((sg) => {
        try {
          return { sg, dateLabel: format(parseISO(sg.starredAt), dateFormat) };
        } catch {
          return { sg, dateLabel: sg.starredAt };
        }
      }),
    [rows, dateFormat],
  );

  const viewport = isVertical
    ? { x: 48, y: 320, w: 624, h: 888, radius: 10 }
    : { x: 560, y: 60, w: 640, h: 600, radius: 10 };

  const visibleRows = Math.floor(viewport.h / rowH);
  const D = Math.max(0, (N - visibleRows + 1) * rowH);
  const scrollY = -pScroll * D;

  const spacerRows = computeSpacerRows({
    N,
    rowH,
    viewportH: viewport.h,
    visibleRows,
  });
  const spacerPx = spacerRows * rowH;

  const settle = interpolate(p, [0.92, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Counter zone type scale.
  const counterSize = isVertical ? 96 : 120;
  const starSize = isVertical ? 56 : 64;
  const underlineMax = isVertical ? 200 : 240;
  const underlineWidth = counterProgress * underlineMax;

  const fadeH = Math.round(viewport.h * 0.12);

  const listViewport = (
    <div
      style={{
        position: "absolute",
        left: viewport.x,
        top: viewport.y,
        width: viewport.w,
        height: viewport.h,
        overflow: "hidden",
        borderRadius: viewport.radius,
        border: `1px solid ${t.border}`,
        background: t.bg,
      }}
    >
      <div
        style={{
          transform: `translateY(${scrollY}px)`,
          willChange: "transform",
        }}
      >
        {formattedRows.map(({ sg, dateLabel }, i) => (
          <Row
            key={`${sg.login}-${i}`}
            stargazer={sg}
            index={i}
            rowH={rowH}
            avatarSize={avatarSize}
            loginSize={loginSize}
            dateLabel={dateLabel}
            accent={accentColor}
            starFill={starColor}
            theme={t}
            isActive={i === N - 1}
            settle={i === N - 1 ? settle : 0}
            showSeparator={i < N - 1}
            opacity={1}
          />
        ))}
        {spacerPx > 0 && (
          <div style={{ height: spacerPx }} aria-hidden="true" />
        )}
      </div>
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          height: fadeH,
          background: `linear-gradient(to bottom, ${t.bg}, transparent)`,
          pointerEvents: "none",
        }}
      />
      <div
        style={{
          position: "absolute",
          bottom: 0,
          left: 0,
          right: 0,
          height: fadeH,
          background: `linear-gradient(to top, ${t.bg}, transparent)`,
          pointerEvents: "none",
        }}
      />
    </div>
  );

  const underline = (
    <div
      style={{
        height: 4,
        width: underlineWidth,
        background: accentColor,
        borderRadius: 2,
      }}
    />
  );

  const repoOwner = repo.split("/")[0] || repo;
  const repoAvatarSize = isVertical ? 28 : 32;
  const repoAvatarSrc =
    repoAvatarUrl ?? `https://unavatar.io/github/${repoOwner}`;

  const repoSlug = (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: 12,
        maxWidth: isVertical ? 600 : 392,
      }}
    >
      <Avatar
        login={repoOwner}
        avatarUrl={repoAvatarSrc}
        size={repoAvatarSize}
        theme={t}
      />
      <div
        style={{
          fontSize: isVertical ? 20 : 24,
          fontWeight: 500,
          color: t.fgMuted,
          fontFamily: FONT_FAMILY,
          overflow: "hidden",
          textOverflow: "ellipsis",
          whiteSpace: "nowrap",
        }}
      >
        {repo}
      </div>
    </div>
  );

  const milestone = milestoneLabel ? (
    <div
      style={{
        fontSize: isVertical ? 22 : 26,
        fontWeight: 600,
        color: accentColor,
        fontFamily: FONT_FAMILY,
        letterSpacing: "-0.01em",
        opacity: interpolate(celebrationProgress, [0.05, 0.3], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        }),
        transform: `translateY(${interpolate(
          celebrationProgress,
          [0.05, 0.3],
          [8, 0],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
        )}px)`,
      }}
    >
      {milestoneLabel}
    </div>
  ) : null;

  // Burst origin: the odometer's optical center in reference px.
  const burstOrigin = isVertical
    ? { x: refW / 2, y: 150 }
    : { x: 276, y: refH / 2 };

  const counterZone = isVertical ? (
    <div
      style={{
        position: "absolute",
        left: 0,
        top: 0,
        width: refW,
        height: 300,
        paddingTop: 72,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: 14,
      }}
    >
      <div style={{ display: "flex", alignItems: "center", gap: 20 }}>
        <StarGlyph size={starSize} fill={starColor} />
        <Odometer current={current} fontSize={counterSize} color={t.fg} />
      </div>
      {underline}
      {repoSlug}
      {milestone}
    </div>
  ) : (
    <div
      style={{
        position: "absolute",
        left: 80,
        top: 0,
        width: 392,
        height: refH,
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "flex-start",
      }}
    >
      <StarGlyph size={starSize} fill={starColor} />
      <div style={{ height: 20 }} />
      <Odometer current={current} fontSize={counterSize} color={t.fg} />
      <div style={{ height: 16 }} />
      {underline}
      <div style={{ height: 20 }} />
      {repoSlug}
      {milestone ? (
        <>
          <div style={{ height: 16 }} />
          {milestone}
        </>
      ) : null}
    </div>
  );

  return (
    <AbsoluteFill style={{ background: t.canvas }}>
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          width: refW,
          height: refH,
          transform: `translate(-50%, -50%) scale(${stageScale})`,
        }}
      >
        {counterZone}
        {listViewport}
        {celebrate && (
          <CelebrationBurst
            progress={celebrationProgress}
            originX={burstOrigin.x}
            originY={burstOrigin.y}
          />
        )}
      </div>
    </AbsoluteFill>
  );
}
